sub tree_check{my($file,$kind,$vectors,$prefix)=@_;my$r=table($file);my(%node,%children,%dist);my@leaves=sort keys%$vectors;my$n=@leaves;for my$q(@$r){my$id=$q->{"${prefix}_name_"};ck("$kind unique node $id",length($id)&&!exists$node{$id});$node{$id}=$q;my$p=$q->{"${prefix}_parent_"};push@{$children{$p}},$id if length($p//'')}ck("$kind full binary node count",@$r==2*$n-1);my($sum,$count)=(0,0);for my$i(0..$#leaves){for my$j($i+1..$#leaves){my($a,$b)=@leaves[$i,$j];my$d=sqrt(sum(map{($vectors->{$a}[$_]-$vectors->{$b}[$_])**2}0..$#{$vectors->{$a}}));$dist{$a}{$b}=$dist{$b}{$a}=$d;$sum+=$d;$count++}}my$norm=$sum/$count;my%active=map{$_=>[$_]}@leaves;my%desc=%active;my$complete=sub{my($a,$b)=@_;max(map{my$x=$_;map{$dist{$x}{$_}}@$b}@$a)};for my$i(reverse 1..$n-1){my$id="CL$i";my@ch=@{$children{$id}//[]};ck("$kind two active children $id",@ch==2&&$active{$ch[0]}&&$active{$ch[1]});next unless@ch==2&&$active{$ch[0]}&&$active{$ch[1]};my$chosen=$complete->($active{$ch[0]},$active{$ch[1]});my@a=sort keys%active;my$min=1e100;for my$j(0..$#a){for my$k($j+1..$#a){my$d=$complete->($active{$a[$j]},$active{$a[$k]});$min=$d if$d<$min}}ck("$kind independent greedy complete-link choice $id",near($chosen,$min));ck("$kind independently normalized height $id",near($node{$id}{"${prefix}_height_"},$chosen/$norm));$desc{$id}=[@{$active{$ch[0]}},@{$active{$ch[1]}}];delete@active{@ch};$active{$id}=$desc{$id}}ck("$kind root retains all leaves",keys(%active)==1&&@{$active{CL1}//[]}==$n);(\%node,\%desc)}
